<script lang="ts">
 import SubmissionTimeline from '$lib/admin/SubmissionTimeline.svelte'; import PageHeader from '$lib/admin/PageHeader.svelte'; import StatusBadge from '$lib/admin/StatusBadge.svelte'; import { formatDate } from '$lib/admin/format'; import { Button } from '$lib/components/ui/button'; import { Textarea } from '$lib/components/ui/textarea'; import { Label } from '$lib/components/ui/label'; import { Alert, AlertDescription } from '$lib/components/ui/alert'; import { Trash2 } from '@lucide/svelte'; import { enhance } from '$app/forms'; import { invalidateAll } from '$app/navigation'; import { toast } from 'svelte-sonner';
 let {data,form}=$props(); const row=$derived(data.letter); let rejection=$state(false); const update=()=>async({update}:any)=>{await update();await invalidateAll();toast.success('Status berhasil diperbarui')};
</script>
<PageHeader title={row.subject} description={`${row.letter_type} · ${row.ministry}`}><StatusBadge status={row.status}/></PageHeader>
{#if form?.error}<Alert variant="destructive" class="mb-4"><AlertDescription>{form.error}</AlertDescription></Alert>{/if}
<div class="grid gap-5 xl:grid-cols-[1fr_340px]"><article class="rounded-xl border bg-card p-6 md:p-10"><p class="text-xs font-semibold uppercase tracking-widest text-orange-500">Draft surat</p><h2 class="mt-2 font-serif text-2xl font-semibold">{row.subject}</h2><div class="mt-7 whitespace-pre-wrap border-t pt-7 font-serif text-[17px] leading-8 text-black-500">{row.body}</div><SubmissionTimeline history={data.timeline} /></article><aside class="space-y-5"><section class="rounded-xl border bg-card p-5"><h2 class="font-serif text-lg font-semibold">Informasi</h2><dl class="mt-4 grid gap-3 text-sm"><div><dt class="text-muted-foreground">Deadline</dt><dd>{formatDate(row.deadline,true)}</dd></div><div><dt class="text-muted-foreground">Pengaju</dt><dd>{row.submitter?.name||'—'}</dd></div><div><dt class="text-muted-foreground">PJ</dt><dd>{row.assigned_pj?.name||'Belum ditetapkan'}</dd></div><div><dt class="text-muted-foreground">Diajukan</dt><dd>{formatDate(row.created_at,true)}</dd></div></dl></section>
{#if data.user.role === "ADMIN_MEDINFO"}<form method="POST" action="?/assign" use:enhance={update} class="space-y-3 rounded-xl border border-blue-100 bg-blue-50/40 p-5"><h2 class="font-serif text-lg font-semibold">Assignment PJ</h2><Label for="assigned_pj_id">Pilih PJ Medinfo</Label><select id="assigned_pj_id" name="assigned_pj_id" required class="h-10 w-full rounded-lg border bg-white px-3 text-sm" value={row.assigned_pj_id || ""}><option value="" disabled>Belum ditetapkan</option>{#each data.queue as item}<option value={item.user_id} disabled={item.is_busy && item.user_id !== row.assigned_pj_id}>{item.user?.name || "PJ Medinfo"}{item.is_busy && item.user_id !== row.assigned_pj_id ? " · Sibuk: " + (item.active_task_title || item.active_request_code || "task aktif") : " · Tersedia"}</option>{/each}</select><Button type="submit" class="w-full bg-blue-500">Tetapkan PJ</Button></form>{/if}
