{#if data.user.role==='ADMIN_MEDINFO' && row.status==='SUBMITTED'}<form method="POST" action="?/status" use:enhance={update} class="rounded-xl border bg-card p-5"><input type="hidden" name="status" value="PENDING_REVIEW"/><p class="mb-3 text-sm text-muted-foreground">{row.assigned_pj_id ? "PJ siap menangani pengajuan ini." : "Tetapkan PJ terlebih dahulu."}</p><Button type="submit" class="w-full bg-blue-500" disabled={!row.assigned_pj_id}>Mulai peninjauan</Button></form>{:else if data.user.role==='ADMIN_MEDINFO' && (row.status==='PENDING_REVIEW' || row.status==='REVISION_SUBMITTED')}<form method="POST" action="?/status" use:enhance={update} class="space-y-3 rounded-xl border bg-card p-5"><h2 class="font-serif text-lg font-semibold">Keputusan</h2><Label for="notes">Catatan review</Label><Textarea id="notes" name="notes" required/><div class="grid gap-2"><Button type="submit" name="status" value="APPROVED" class="bg-green-700">Setujui</Button><Button type="submit" name="status" value="REVISION_REQUIRED" variant="outline">Minta revisi</Button><Button type={rejection?'submit':'button'} name="status" value="REJECTED" variant="destructive" onclick={()=>rejection=true}>Tolak</Button></div></form>{/if}
